from typing import List, Optional
from pydantic import BaseModel, Field


class MarketingResult(BaseModel):
    """The structured marketing content generated by the Marketing Agent."""
    instagram_caption: str = Field(description="Visual-first social post with emoji hooks.")
    facebook_post: str = Field(description="Community focused Facebook post copy.")
    linkedin_post: str = Field(description="Professional and educational B2B summary post.")
    twitter_x_post: str = Field(description="Concise 280-character micro-blog post.")
    whatsapp_promotion: str = Field(description="Short informal broadcast copy with bullet points.")
    email_campaign: str = Field(description="Rich email copy including Subject Line, Preheader, Body, and CTA.")
    cta: str = Field(description="Call-to-action button copy (e.g. Enroll Now, Get Your Kit).")
    promotional_headline: str = Field(description="Catchy banners hero text.")
    banner_text: str = Field(description="Under headline support banner copy.")
    hashtags: List[str] = Field(description="Curated high-reach social hashtags.")


class MarketingResponse(BaseModel):
    """Structured response wrap returned by the Marketing Agent."""
    status: str = Field(description="Result of execution: 'success' or 'failed'.")
    errors: List[str] = Field(default_factory=list, description="List of processing error messages.")
    marketing: Optional[MarketingResult] = Field(default=None, description="The validated structured marketing copy.")
